<?php $title='New Invoice';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><h1>New Invoice</h1></div><form class="panel form" method="post" action="<?=route('invoices')?>"><?=csrf_field()?><div class="form-grid"><label>Invoice number<input name="invoice_number" placeholder="INV-..." required></label><label>Client<select name="client_id" required><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['full_name'])?></option><?php endforeach;?></select></label><label>Project<select name="project_id"><option value="">—</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Due date<input type="date" name="due_date"></label><label>Tax amount<input type="number" name="tax_amount" step="0.01" value="0"></label><label>Discount<input type="number" name="discount" step="0.01" value="0"></label><label class="wide">Notes<textarea name="notes" rows="3"></textarea></label></div><h2>Items</h2><div id="invoice-items" class="item-list"><div class="item-row"><input name="item_description[]" placeholder="Service / item"><input name="item_quantity[]" type="number" step="0.01" value="1"><input name="item_price[]" type="number" step="0.01" value="0"></div></div><button type="button" class="secondary" onclick="addInvoiceItem()">+ Add item</button> <button class="primary">Create invoice</button></form><?php require __DIR__.'/../layouts/footer.php';?>
